"use strict";

const formulario = document.querySelector("#formulario");
const campoNumero = document.querySelector("#numero");
const resultado = document.querySelector("#resultado");

formulario.addEventListener("submit", (event) => {
  event.preventDefault();

  // Se comprueba el texto antes de convertirlo: una entrada vacía se convertiría en cero.
  const texto = campoNumero.value.trim();
  const numero = Number(texto);
  if (texto === "" || !Number.isFinite(numero) || numero % 1 !== 0) {
    resultado.textContent = "Introduce un número entero válido.";
    return;
  }

  resultado.textContent = numero % 2 !== 0 ? "Es impar." : "Es par.";
});

